// C++17 Fold Expressions for Efficiency

template<typename... T>
void print_pack_debug(T... args) {
    // Unary Left Fold (printing/executing side effects)
    (std::cout << args << ' ', ...);
}

template<typename... Args>
auto sum_variadic(Args... args) {
    // Binary Left Fold: (A + B) + C + ...
    return (0 + ... + args);
}

template<typename... Functors>
void execute_all(Functors... funcs) {
    // Unary Right Fold: Executes all functions/callables
    (funcs(), ...); 
}

// Variadic Class Template Example

template<typename... T>
struct PackTraits {
    static constexpr size_t Count = sizeof...(T);
    static constexpr bool Empty = Count == 0;
};
